export function chooseProvider(candidates=[],{truthRequired=null,maxAgeMs=Infinity,now=Date.now()}={}){const ok=candidates.filter(x=>x.enabled!==false&&x.health!=='DOWN'&&(!truthRequired||x.truthClass===truthRequired)&&(!x.observedAt||now-Number(new Date(x.observedAt))<=maxAgeMs)).sort((a,b)=>(a.priority??99)-(b.priority??99));return ok[0]?{provider:ok[0],reason:'BEST_VALID_PROVIDER'}:{provider:null,reason:'NO_VALID_PROVIDER'}}
